Scope controls how often the fixture is constructed and torn down across the test run.

```python
import pytest

@pytest.fixture(scope="function")  # default
def per_test():
    print("new per test")
    yield object()

@pytest.fixture(scope="class")
def per_class():
    yield object()

@pytest.fixture(scope="module")
def per_module():
    yield object()

@pytest.fixture(scope="session")
def per_session():
    yield object()
```

Rules of thumb: `function` for anything mutable (the default, safest). `class` when grouping related tests around shared state. `module` for expensive per-file setup like loading a fixture dataset. `session` for truly global, read-only resources (a compiled wheel, a Docker container, a warm HTTP client). Higher-scoped fixtures cannot depend on lower-scoped ones. If you need a session DB with per-test isolation, wrap each test in a transaction that rolls back on teardown.

Return a function from the fixture so tests can call it with overrides.

```python
import pytest
from dataclasses import dataclass, field

@dataclass
class User:
    id: int
    email: str
    roles: list = field(default_factory=list)

@pytest.fixture
def user_factory():
    counter = {"n": 0}
    def _make(**overrides):
        counter["n"] += 1
        defaults = {"id": counter["n"], "email": f"u{counter['n']}@ex.com", "roles": []}
        defaults.update(overrides)
        return User(**defaults)
    return _make

def test_admin(user_factory):
    admin = user_factory(roles=["admin"])
    regular = user_factory()
    assert admin.roles == ["admin"]
    assert regular.id != admin.id
```

The factory fixture pattern avoids the combinatorial explosion of having one fixture per flavour of object. A test can create as many users as needed with just the fields that matter, and defaults stay in one place. For more structured needs, consider `factory-boy` or `polyfactory`, but a plain factory fixture covers 80% of cases.

Just request the dependency by name. pytest resolves the graph.

```python
import pytest

@pytest.fixture
def config():
    return {"host": "localhost", "port": 5432}

@pytest.fixture
def db_url(config):
    return f"postgres://{config['host']}:{config['port']}/test"

@pytest.fixture
def engine(db_url):
    # imagine sqlalchemy.create_engine(db_url)
    return {"url": db_url, "connected": True}

@pytest.fixture
def session(engine):
    sess = {"engine": engine, "tx": []}
    yield sess
    sess["tx"].clear()

def test_session_wired(session):
    assert session["engine"]["url"] == "postgres://localhost:5432/test"
```

pytest builds a DAG of fixtures and creates each one at most once per its scope during a test. A test that asks for `session` gets `config` and `engine` constructed transitively. This composition lets you keep each fixture single-purpose and remix them per test, which is far cleaner than a single monolithic `setup` helper.

Create the app, push an application context, yield the client, then pop the context.

```python
import pytest
from myapp import create_app, db

@pytest.fixture
def app():
    app = create_app({"TESTING": True, "SQLALCHEMY_DATABASE_URI": "sqlite:///:memory:"})
    with app.app_context():
        db.create_all()
        yield app
        db.session.remove()
        db.drop_all()

@pytest.fixture
def client(app):
    return app.test_client()

@pytest.fixture
def runner(app):
    return app.test_cli_runner()

def test_homepage(client):
    rv = client.get("/")
    assert rv.status_code == 200
    assert b"Welcome" in rv.data

def test_create_cli(runner):
    result = runner.invoke(args=["init-db"])
    assert "Initialized" in result.output
```

The `app_context()` block ensures Flask's `current_app` proxy and SQLAlchemy session work. `test_client()` gives an HTTP-level interface that does not require a running server. `test_cli_runner()` exercises registered Click commands.

Mark the parameter as `indirect` so pytest passes values through the fixture instead of directly.

```python
import pytest

@pytest.fixture
def client(request):
    backend = request.param
    if backend == "sqlite":
        return {"engine": "sqlite", "url": ":memory:"}
    elif backend == "postgres":
        return {"engine": "postgres", "url": "postgres://localhost/test"}
    raise ValueError(backend)

@pytest.mark.parametrize("client", ["sqlite", "postgres"], indirect=True)
def test_connect(client):
    assert "url" in client
```

The fixture sees each parameter in `request.param`. The test receives the fully constructed object. This is the clean way to run the same test suite against multiple real implementations. You can combine direct and indirect:

```python
@pytest.mark.parametrize("client, input, expected", [
    ("sqlite", 1, 1), ("postgres", 1, 1),
], indirect=["client"])
def test_echo(client, input, expected):
    assert input == expected
```

Only `client` is indirect; `input` and `expected` are passed directly.

Register the marker, add a CLI flag, and skip unless enabled.

```python
# conftest.py
import pytest

def pytest_addoption(parser):
    parser.addoption("--runslow", action="store_true", default=False,
                     help="run tests marked @pytest.mark.slow")

def pytest_configure(config):
    config.addinivalue_line("markers", "slow: mark test as slow to run")

def pytest_collection_modifyitems(config, items):
    if config.getoption("--runslow"):
        return
    skip_slow = pytest.mark.skip(reason="need --runslow to run")
    for item in items:
        if "slow" in item.keywords:
            item.add_marker(skip_slow)
```

Usage:

```python
@pytest.mark.slow
def test_expensive_integration():
    ...
```

Default `pytest` skips it. `pytest --runslow` runs it. Alternative one-liner without custom flag: use the marker system directly with `pytest -m "not slow"` as your default CI invocation. Both patterns are valid; the opt-in flag is more explicit for newcomers on the team.

Use `freezegun` or inject a clock dependency.

```python
from datetime import datetime, timezone
from freezegun import freeze_time

def timestamp_log(message):
    return f"[{datetime.now(timezone.utc).isoformat()}] {message}"

@freeze_time("2026-01-15T10:00:00Z")
def test_timestamp_log():
    assert timestamp_log("boot") == "[2026-01-15T10:00:00+00:00] boot"

@freeze_time("2026-01-15")
def test_time_travel():
    from freezegun import freeze_time as ft
    with ft("2027-06-01"):
        assert datetime.now().year == 2027
    assert datetime.now().year == 2026
```

Injected-clock alternative, no dependency:

```python
class Service:
    def __init__(self, clock=datetime.utcnow):
        self._clock = clock
    def now(self):
        return self._clock()

def test_service_clock():
    svc = Service(clock=lambda: datetime(2026, 1, 15))
    assert svc.now().year == 2026
```

Dependency injection is cleaner long-term, but `freezegun` is great for existing code you cannot refactor.

Assign a `side_effect` callable instead of a fixed `return_value`.

```python
from unittest.mock import patch, MagicMock

def fake_get(url, *args, **kwargs):
    if url.endswith("/users"):
        return MagicMock(status_code=200, json=lambda: [{"id": 1}])
    if url.endswith("/health"):
        return MagicMock(status_code=200, json=lambda: {"ok": True})
    return MagicMock(status_code=404, json=lambda: {"error": "not found"})

@patch("myapp.client.requests.get", side_effect=fake_get)
def test_multi(mock_get):
    from myapp.client import fetch
    assert fetch("users")[0]["id"] == 1
    assert fetch("health")["ok"] is True
    assert fetch("unknown") is None
    assert mock_get.call_count == 3
```

For simpler cases with a fixed sequence, `side_effect` also accepts an iterable:

```python
mock_get.side_effect = [resp_a, resp_b, ConnectionError("boom")]
```

Each call pops the next value; if it is an exception class or instance, it is raised. In real projects, prefer the `responses` or `respx` libraries, which hook at the transport layer and let you register URL patterns declaratively.

Patch the reference used by the code under test.

```python
# myapp/retry.py
import time

def retry(fn, attempts=3, backoff=1.0):
    for i in range(attempts):
        try:
            return fn()
        except Exception:
            if i == attempts - 1:
                raise
            time.sleep(backoff * (2 ** i))
```

```python
# test_retry.py
from unittest.mock import patch, MagicMock
import pytest
from myapp.retry import retry

@patch("myapp.retry.time.sleep")
def test_retry_exponential(mock_sleep):
    fn = MagicMock(side_effect=[RuntimeError, RuntimeError, "ok"])
    assert retry(fn, attempts=3, backoff=0.5) == "ok"
    waits = [c.args[0] for c in mock_sleep.call_args_list]
    assert waits == [0.5, 1.0]
    assert fn.call_count == 3
```

We not only assert the function eventually returned, but also that the backoff schedule was correct. Patching `myapp.retry.time.sleep` (not `time.sleep`) ensures we only affect this module, keeping the test targeted.

`patch.object` handles both; target the class and the method name.

```python
class Clock:
    @classmethod
    def now(cls):
        import datetime
        return datetime.datetime.utcnow()

    @staticmethod
    def timezone():
        return "UTC"

from unittest.mock import patch
import datetime

def test_clock_now():
    with patch.object(Clock, "now", return_value=datetime.datetime(2026, 1, 1)):
        assert Clock.now().year == 2026

def test_clock_tz():
    with patch.object(Clock, "timezone", return_value="America/Los_Angeles"):
        assert Clock.timezone() == "America/Los_Angeles"
```

For instance methods, patching the class replaces the method on all instances for the duration of the patch. For an already-instantiated object's method, `patch.object(instance, "method")` swaps it just on that instance. Remember `autospec=True` if you want signature checking; classmethods are tricky because `cls` is injected, so autospec is worth it to avoid shape mismatches.

Hypothesis generates many inputs and checks invariants instead of hardcoded examples.

```python
from hypothesis import given, strategies as st

def reverse(xs):
    return xs[::-1]

@given(st.lists(st.integers()))
def test_reverse_twice_is_identity(xs):
    assert reverse(reverse(xs)) == xs

@given(st.lists(st.integers()))
def test_reverse_preserves_length(xs):
    assert len(reverse(xs)) == len(xs)

@given(st.lists(st.integers(), min_size=1))
def test_reverse_swaps_ends(xs):
    r = reverse(xs)
    assert r[0] == xs[-1]
    assert r[-1] == xs[0]
```

Each test runs ~100 randomized inputs by default. When one fails, Hypothesis *shrinks* it to the smallest counterexample: e.g. `[0]` rather than `[-837293, 4, 100]`. That shrink is the magic: your bug reports are minimal, not noisy. Save found failures to a local database so the next run replays them first.

The `strategies` module is your palette.

```python
from hypothesis import given, strategies as st

@given(st.integers(min_value=0, max_value=1000))
def test_nat(n):
    assert n >= 0

@given(st.floats(allow_nan=False, allow_infinity=False))
def test_finite_float(x):
    assert x == x  # NaN would break this

@given(st.text(alphabet="abc", min_size=1, max_size=10))
def test_small_text(s):
    assert set(s) <= set("abc")

@given(st.lists(st.integers(), min_size=1, max_size=20, unique=True))
def test_unique_list(xs):
    assert len(set(xs)) == len(xs)

@given(st.dictionaries(
    keys=st.text(min_size=1, max_size=5),
    values=st.integers(),
    max_size=10,
))
def test_dict(d):
    assert all(isinstance(k, str) for k in d)

@given(st.one_of(st.none(), st.integers(), st.text()))
def test_union(x):
    assert x is None or isinstance(x, (int, str))
```

Key builders: `integers`, `floats`, `text`, `binary`, `booleans`, `none`, `lists`, `tuples`, `dictionaries`, `sets`, `datetimes`, `uuids`, `emails`, `ip_addresses`, `from_regex`, `sampled_from`, `one_of`, `just`, and `builds` for composing dataclasses.

`@st.composite` lets one strategy depend on another's drawn value.

```python
from hypothesis import given, strategies as st

@st.composite
def sorted_lists(draw, min_size=0, max_size=50):
    xs = draw(st.lists(st.integers(), min_size=min_size, max_size=max_size))
    return sorted(xs)

@st.composite
def index_and_list(draw):
    xs = draw(st.lists(st.integers(), min_size=1, max_size=20))
    i = draw(st.integers(min_value=0, max_value=len(xs) - 1))
    return xs, i

@given(sorted_lists())
def test_sorted_is_sorted(xs):
    assert xs == sorted(xs)

@given(index_and_list())
def test_index_in_bounds(pair):
    xs, i = pair
    assert 0 <= i < len(xs)
    xs[i]  # does not raise
```

Composite strategies are essential when you need correlated inputs: a list plus a valid index into it, a date plus a time in the same timezone, a graph plus a node in it. Call `draw(other_strategy)` to pull a value; return whatever shape you need. They compose cleanly with `@given`.

`assume(condition)` tells Hypothesis this example is uninteresting; generate another.

```python
from hypothesis import given, assume, strategies as st

def divide(a, b):
    return a / b

@given(st.integers(), st.integers())
def test_divide(a, b):
    assume(b != 0)
    result = divide(a, b)
    assert isinstance(result, float)

@given(st.text())
def test_ascii_only_roundtrip(s):
    assume(s.isascii())
    assert s.encode("ascii").decode("ascii") == s
```

`assume` is useful but has a cost: if you discard too many inputs, Hypothesis raises `Unsatisfiable`. The better fix is to narrow the strategy so you do not generate bad inputs in the first place:

```python
@given(st.integers(), st.integers().filter(lambda b: b != 0))
def test_divide_narrow(a, b):
    divide(a, b)

# or best:
@given(st.integers(), st.integers(min_value=1))  # strictly positive
def test_divide_pos(a, b):
    divide(a, b)
```

Rule of thumb: use `assume` for rare-edge filtering, custom strategies for common constraints.

Model an object as a state machine; Hypothesis drives it with random action sequences.

```python
from hypothesis.stateful import RuleBasedStateMachine, rule, invariant
from hypothesis import strategies as st

class Stack:
    def __init__(self):
        self._data = []
    def push(self, x):
        self._data.append(x)
    def pop(self):
        return self._data.pop()
    def peek(self):
        return self._data[-1]
    def __len__(self):
        return len(self._data)

class StackMachine(RuleBasedStateMachine):
    def __init__(self):
        super().__init__()
        self.stack = Stack()
        self.model = []  # reference implementation

    @rule(v=st.integers())
    def push(self, v):
        self.stack.push(v)
        self.model.append(v)

    @rule()
    def pop(self):
        if self.model:
            assert self.stack.pop() == self.model.pop()

    @invariant()
    def same_length(self):
        assert len(self.stack) == len(self.model)

TestStack = StackMachine.TestCase
```

Hypothesis fuzzes orderings of push/pop, ensuring the real stack behaves like the simple list model. Rules are actions, invariants run after each rule. When a discrepancy surfaces, the shrinking process finds the shortest sequence that exposes the bug.

Shrinking reduces a failing example to a minimal form so the bug is easier to diagnose.

```python
from hypothesis import given, strategies as st

def buggy_sum(xs):
    # bug: returns wrong answer when list contains -1
    total = 0
    for x in xs:
        if x == -1:
            continue
        total += x
    return total

@given(st.lists(st.integers()))
def test_sum(xs):
    assert buggy_sum(xs) == sum(xs)
```

When this fails, output looks like:

```
Falsifying example: test_sum(
    xs=[-1],
)
```

Not `[-1, 837, -29304]`. Hypothesis tries removing elements, moving values toward 0, shortening strings, and so on. The final example is *the* smallest trigger. Add `@example(xs=[-1])` to pin it as a regression test:

```python
from hypothesis import given, example, strategies as st

@given(st.lists(st.integers()))
@example(xs=[-1])
def test_sum(xs):
    ...
```

Hypothesis also saves failures to `.hypothesis/examples/` and replays them first, so once seen a bug is never lost.

Three independent properties pin down correctness without reimplementing sort.

```python
from hypothesis import given, strategies as st
from collections import Counter

def my_sort(xs):
    return sorted(xs)

@given(st.lists(st.integers()))
def test_sort_is_sorted(xs):
    r = my_sort(xs)
    assert all(r[i] <= r[i+1] for i in range(len(r) - 1))

@given(st.lists(st.integers()))
def test_sort_preserves_multiset(xs):
    assert Counter(my_sort(xs)) == Counter(xs)

@given(st.lists(st.integers()))
def test_sort_idempotent(xs):
    once = my_sort(xs)
    assert my_sort(once) == once
```

Three properties cover: (1) output is ordered, (2) no elements added or dropped, (3) sorting twice equals sorting once. Together these nearly pin down sort. An impostor like "sort by discarding odd numbers" fails property 2; "reverse instead of sort" fails 1; "shuffle" fails 1 and 3. This is the shape of a good property-based test suite: small properties that together constrain behavior tightly.

Request fixtures on the test function; `@given` provides extra args.

```python
import pytest
from hypothesis import given, strategies as st

@pytest.fixture
def store():
    return {}

@given(key=st.text(min_size=1, max_size=20), value=st.integers())
def test_store_set_get(store, key, value):
    store[key] = value
    assert store[key] == value
```

But be careful: `store` is constructed *once* per pytest test function, but `@given` runs the body ~100 times. State leaks across iterations. If you need fresh state each Hypothesis iteration, construct it inside:

```python
@given(key=st.text(min_size=1), value=st.integers())
def test_store_clean(key, value):
    store = {}  # fresh every iteration
    store[key] = value
    assert store[key] == value
```

Or use a function-scoped fixture that yields a factory:

```python
@pytest.fixture
def store_factory():
    return lambda: {}

@given(key=st.text(min_size=1), value=st.integers())
def test_store_factory(store_factory, key, value):
    store = store_factory()
    store[key] = value
```

Hypothesis warns about fixture reuse since 6.x because the issue is so common.

Round-trip test: encoded bytes should decode back to the original.

```python
import struct
from hypothesis import given, strategies as st

def encode_u32(n):
    if n < 0 or n > 2**32 - 1:
        raise ValueError("out of range")
    return struct.pack(">I", n)

def decode_u32(b):
    if len(b) != 4:
        raise ValueError("need 4 bytes")
    return struct.unpack(">I", b)[0]

@given(st.integers(min_value=0, max_value=2**32 - 1))
def test_roundtrip(n):
    assert decode_u32(encode_u32(n)) == n

@given(st.binary(min_size=4, max_size=4))
def test_decode_of_random_bytes(b):
    n = decode_u32(b)
    assert 0 <= n < 2**32
    assert encode_u32(n) == b

@given(st.integers())
def test_bounds(n):
    import pytest
    if not (0 <= n < 2**32):
        with pytest.raises(ValueError):
            encode_u32(n)
```

Three complementary properties: encode->decode roundtrip, decode->encode roundtrip on random bytes, and out-of-range rejection. Together they catch off-by-one boundary bugs, endianness mistakes, and silent truncation.

`sampled_from` picks one of a fixed set; `just` always returns the same value.

```python
from hypothesis import given, strategies as st

STATUS = ["pending", "active", "closed", "archived"]

@given(st.sampled_from(STATUS))
def test_status_is_valid(status):
    assert status in STATUS

@given(st.lists(st.sampled_from(STATUS), min_size=1, max_size=10))
def test_many_statuses(statuses):
    assert all(s in STATUS for s in statuses)

# just: a strategy that always yields one value; useful in one_of
@given(st.one_of(st.just(None), st.integers()))
def test_maybe_int(x):
    assert x is None or isinstance(x, int)

# sampled_from for enums
from enum import Enum
class Color(Enum):
    RED = 1; GREEN = 2; BLUE = 3

@given(st.sampled_from(list(Color)))
def test_color(c):
    assert isinstance(c, Color)
```

`sampled_from` is ideal for closed categorical domains: enum values, HTTP methods, valid country codes. Hypothesis can also shrink toward earlier items in the list, so put "simpler" values first (e.g. `""` before long strings) to get cleaner counterexamples.

Hypothesis ships high-quality strategies for common web formats.

```python
from hypothesis import given, strategies as st
import re
import uuid

@given(st.emails())
def test_email_has_at(e):
    assert "@" in e
    assert e.count("@") == 1

@given(st.uuids())
def test_uuid_version(u):
    assert isinstance(u, uuid.UUID)

@given(st.ip_addresses(v=4))
def test_ipv4(addr):
    parts = str(addr).split(".")
    assert len(parts) == 4
    assert all(0 <= int(p) <= 255 for p in parts)

# URLs: from_regex is the reliable way
URL = st.from_regex(
    r"^https?://[a-z]{3,10}\.(com|net|org)(/[a-z]{0,10}){0,3}$",
    fullmatch=True,
)

@given(URL)
def test_url_scheme(u):
    assert u.startswith(("http://", "https://"))
```

`emails()` produces RFC-compliant addresses; `uuids()` produces valid UUIDs; `ip_addresses(v=4|6)` gives `IPv4Address` / `IPv6Address` objects. For URL generation use `from_regex` with `fullmatch=True` so the entire string must match, or compose path/host manually with `builds(urlparse.urlunparse, ...)`.

Write a property any addition must satisfy, then run it.

```python
from hypothesis import given, strategies as st

def my_add(a, b):
    # bug: special-cases 0 incorrectly
    if b == 0:
        return a + 1
    return a + b

@given(st.integers(), st.integers())
def test_commutative(a, b):
    assert my_add(a, b) == my_add(b, a)

@given(st.integers())
def test_identity(a):
    assert my_add(a, 0) == a  # this fails, shrunk to a=0

@given(st.integers(), st.integers(), st.integers())
def test_associative(a, b, c):
    assert my_add(my_add(a, b), c) == my_add(a, my_add(b, c))
```

Hypothesis reports `Falsifying example: test_identity(a=0)` because `my_add(0, 0) == 1`, not 0. The identity property caught it on the smallest possible input. The broader lesson: for math-ish functions, write the algebraic laws (identity, commutativity, associativity, distributivity) as properties. They constrain behavior better than any hand-picked examples because they must hold for *every* input, not just the cases a human thought to try.

Compose strategies that mirror your schema's structure.

```python
from hypothesis import given, strategies as st

# API contract: POST /users expects {name: str, age: int>=0, tags: list[str]}
user_payload = st.fixed_dictionaries({
    "name": st.text(min_size=1, max_size=50),
    "age": st.integers(min_value=0, max_value=150),
    "tags": st.lists(st.text(min_size=1, max_size=20),
                     max_size=10, unique=True),
})

# optional fields via dictionaries with optional keys
user_with_optional = st.fixed_dictionaries(
    mapping={
        "name": st.text(min_size=1),
        "age": st.integers(min_value=0),
    },
    optional={
        "email": st.emails(),
        "bio": st.text(max_size=500),
    },
)

@given(user_payload)
def test_accepts_valid_payload(payload):
    from myapp.validator import validate_user
    assert validate_user(payload) is True

@given(user_with_optional)
def test_accepts_with_optional(payload):
    from myapp.validator import validate_user
    assert validate_user(payload) is True
    for k in payload:
        assert k in {"name", "age", "email", "bio"}
```

`fixed_dictionaries` forces all keys; `optional=` lets Hypothesis sometimes include them. This mirrors OpenAPI `required` vs `optional` behavior exactly.

Use careful float strategies and tolerance-based assertions.

```python
import math
from hypothesis import given, strategies as st, assume

def normalize(x, y):
    n = math.hypot(x, y)
    if n == 0:
        return (0.0, 0.0)
    return (x / n, y / n)

@given(
    st.floats(allow_nan=False, allow_infinity=False, min_value=-1e6, max_value=1e6),
    st.floats(allow_nan=False, allow_infinity=False, min_value=-1e6, max_value=1e6),
)
def test_unit_length(x, y):
    assume(math.hypot(x, y) > 1e-9)  # skip degenerate zero vectors
    nx, ny = normalize(x, y)
    assert math.isclose(math.hypot(nx, ny), 1.0, abs_tol=1e-9)

@given(st.floats(allow_nan=False, allow_infinity=False, min_value=-100, max_value=100))
def test_doubling(x):
    assert math.isclose(x + x, 2 * x)
```

Tips: always exclude NaN/Inf unless the function must handle them. Use `math.isclose` (or `numpy.testing.assert_allclose`) for float equality, never `==`. Bound magnitudes to avoid overflow or catastrophic cancellation when the property would not actually be meaningful at the extremes.

Use `@example(...)` for regression tests and specific tricky inputs.

```python
from hypothesis import given, example, strategies as st

def reverse_words(s):
    return " ".join(s.split()[::-1])

@given(st.text())
@example(s="")
@example(s="   ")
@example(s="hello world")
@example(s="\tnewline\nmixed  spaces")
def test_reverse_words_roundtrip(s):
    once = reverse_words(s)
    twice = reverse_words(once)
    # split() collapses whitespace, so we compare on the normalized form
    assert reverse_words(twice) == once
```

`@example` decorators run *before* any random examples and are guaranteed to execute every time. Use them for:
- Bugs you found in production (pin them to prevent regression)
- Known edge cases (empty string, zero, None, single-element list)
- Performance boundary cases (max allowed size)

When Hypothesis shrinks a failure, it prints the counterexample in `@example`-ready form so you can paste it straight in.

Model it as a state machine and compare against a dict.

```python
from collections import OrderedDict
from hypothesis import strategies as st
from hypothesis.stateful import RuleBasedStateMachine, rule, invariant, precondition

class LRUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self._data = OrderedDict()
    def get(self, k):
        if k not in self._data: return None
        self._data.move_to_end(k)
        return self._data[k]
    def put(self, k, v):
        if k in self._data: self._data.move_to_end(k)
        self._data[k] = v
        if len(self._data) > self.cap:
            self._data.popitem(last=False)

class LRUMachine(RuleBasedStateMachine):
    def __init__(self):
        super().__init__()
        self.cap = 3
        self.cache = LRUCache(self.cap)

    @rule(k=st.integers(min_value=0, max_value=10),
          v=st.integers())
    def put(self, k, v):
        self.cache.put(k, v)

    @rule(k=st.integers(min_value=0, max_value=10))
    def get(self, k):
        self.cache.get(k)

    @invariant()
    def capacity(self):
        assert len(self.cache._data) <= self.cap

TestLRU = LRUMachine.TestCase
```

The capacity invariant is checked after every rule. To test correctness, add a parallel reference (dict + a list tracking order) and assert equivalence on every `get`.

